import{_ as b,o as p,c as l,ah as e}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"동박","slug":"동박","link":"#동박","children":[]},{"level":2,"title":"대우건설","slug":"대우건설","link":"#대우건설","children":[]},{"level":2,"title":"시추","slug":"시추","link":"#시추","children":[]},{"level":2,"title":"소비재","slug":"소비재","link":"#소비재","children":[{"level":3,"title":"외제차 독3사","slug":"외제차-독3사","link":"#외제차-독3사","children":[]}]},{"level":2,"title":"장이 좋다","slug":"장이-좋다","link":"#장이-좋다","children":[]}],"relativePath":"club/MIRO/260509 주식 스터디.md","filePath":"club/MIRO/260509 주식 스터디.md"}'),a={name:"club/MIRO/260509 주식 스터디.md"};function i(t,r,o,n,h,d){return p(),l("div",null,[...r[0]||(r[0]=[e('<h2 id="동박" tabindex="-1">동박 <a class="header-anchor" href="#동박" aria-label="Permalink to &quot;동박&quot;">​</a></h2><p>음극재에 바른다<br> 배터리가 왜 좋나<br> 배터리 사용처</p><ol><li><p>ESS</p><ol><li>태양광 단점</li><li>간헐성, 페로브 +ESS랑 깔아야함</li></ol></li><li><p>전기차<br> 휘발유값 오름<br> 큰차 1000km감</p></li></ol><h2 id="대우건설" tabindex="-1">대우건설 <a class="header-anchor" href="#대우건설" aria-label="Permalink to &quot;대우건설&quot;">​</a></h2><p>매출 비중<br> 주택사업 70%</p><p>우크라이나 재건주<br> 지어줬던 애들이 제일 빨리 지어줌<br> 한국에는 X<br> 건설사마다 느낌이 다름<br> 대우 리비아, 이라크 향이 많음<br> 영향이 X</p><p>부채비율이 너무 많음 펌핑해서 해소하려는건가?<br> 정유화학시설 부숴짐 지어야 겠죠?<br> ENA<br> 장비주 사라~</p><h2 id="시추" tabindex="-1">시추 <a class="header-anchor" href="#시추" aria-label="Permalink to &quot;시추&quot;">​</a></h2><p>미국에서 시추 할떄 육상에서 뭐 해야하죠?<br> 미국에는 전지억에 CL층이라는 게 있음 점토<br> 한방울씩 석유 천연가스가 있음. 전에는 기술이 없어서 못뽑았는데<br> 이제는 뽑을 수 있음<br> CL유면 CL층에 기름 CL가스면 층에 있는 가스<br> 계속 시추하다보니 이제 잘 안나옴<br> 구멍 뚫고 안파</p><p>유가가 낮으면 해상시추<br> 파기 힘든데 파면 정말 많이 나옴<br> 골든 트라이 앵글</p><p>미국앞마당이라 중동 영향 안받고 싶어서 파고있겠지</p><p>유가가 낮으면 육상 비율이 낮고 해상비율이 늘어남<br> 유가가 높아지면 아무나 할 수 있는 육상도 늘어남</p><p>유가가 낮든 높든 해상은 늘어난다<br> 트랜스 오션 8세대1,2대 있음<br> 노블이 7세대 많음<br> NOV는 드릴 부품 만드는 회사<br> 언제 튈지 모름</p><p>가스전 개발<br> 카타르가 막혔으니까..<br> 이제는 LNG중심이 미국이 될 수 ㅇ ㅣㅆ지 않나<br> 남는게 가스니까<br> 미국이 기회를 과연 놓칠까?<br> 카타르도 바보는 아닌데 지정학적으로 막혀있으니까</p><p>송유관, 가스관을 뚫어서 중동에서 시도 하지 않을까<br> 아랍에미리트 오펙 탈퇴<br> 왜 했을까<br> 미국 빨겠다<br> 프리지아 항구<br> 호르무즈 밖에 있음<br> 송유관 설치해서 다이렉트로 하면 호르무즈 리스크 없어짐<br> 그럴려면 송유관 더 설치 해야 겠죠?<br> 아랍에미리트<br> 국내에서 생산되는 강관, 송유관 글로 갈 수있음</p><p>지금 안뽑으면 비싸게 못파니까..<br> 휴스틸</p><p>LNG는 미국이 안좋칠 것 같음<br> 알레스카 쉘가스 사가줄 호구 찾기..<br> 허브 많이 짓겠지<br> 한국카본 LNG저장 할떄 쓰는거<br> 액화 시켜서 옮기는데 ,<br> 압력도 높고 니켈로 감싸야함 (열전도) 포스코가 잘함<br> 카본도 들어가야함 (한국카본 이미 비쌈)</p><p>나트륨 배터리<br> 현재 차에 배터리</p><p>납축배터리<br> 전해질: 황산<br> 왜 중요한가? 중국에서 5월 부터 황상수출 금지<br> 납축배터리값이 올라감<br> 새로운 차는 나트륨배터리를 쓰자는 이야기가 많이 나올 것<br> 국내에 나트륨 배터리 관련회사가 많이 없음</p><p>왜 나트륨 배터리가 되어야하는거<br> 전기차에LFP가 들어갈 건데<br> 싸고 유통기한이 길다<br> 대신 충전량이 조금 작음<br> 단점이 온도가 낮으면 방전</p><p>지금 전기차 원래 배터리와 보조 배터리. 보조는 다른 리튬배터리<br> 본배터리 걸어두면 방전. 그래서 보조 배터리<br> 리튬이니까 비싸다.<br> 나트륨은 바다에 널려있음</p><p>온도낮으면 방전<br> 그래서 보조해야할게 있음 LFP?</p><p>중국에서 나트륨 배터리 밀고있음<br> 탄산리튬에서 리튬추출시 폐기물 많음<br> 중국이 80프로<br> 한국, 미국은 환경단체가 지랄<br> 중국 자체에서는 리튬이 많이 없음<br> 호주 칠레 아르헨티나에 많음<br> 중국에 리튬 안준다 하면? 그게 무서움<br> 결국에는 이란에 값싼 원유가 안오면<br> 전기로 다 바꿔야함<br> 저장공간이 리튬<br> 리튬이 안들어오면 비상</p><p>리툼에 없어도 되는 나트륨을 밀고 있음<br> 중국이 나트륨배터리 밀면 한국에 수혜받을게 분명 있을 것이다.</p><p>아라미드 원료, 나트륨 배터리로 바꾸려고 노력중</p><p>음극재가 좋으면 유통기한이 김<br> ESS까지는 예쁜 음극재가 안나옴<br> 유통기한이 3배차이<br> 가격에 3배차이 나야되는거 아님? 단순논리로</p><p>LFP는 5년이 지나도 충전 단가가 80프로는 차징이됨<br> 나트륨은 유통기한이 짧다</p><p>무조건 처음은 납축배터리 시장이어야함<br> 1년에 자동차 납축배터리 교체.<br> 1회에 15, 20만</p><p>나트륨 가면 차 폐차까지 쓸거다.<br> 빨리 충전 방전은 괜ㅊ낳은데<br> ESS처럼 충방전 여러번은 리스크가 큼<br> 유통기한이 안되기 떄문에</p><p>한국에 있는 나트륨 배터리 소재 만드는<br> 한국 업체가 3등 기술적으로 괜찮다</p><p>6개월전 LNF 더 간다</p><p>LNF 만든</p><p>LFP 캐퍼가 6만<br> SDI에서 4.1만톤을 계약<br> 1.9만<br> 증설해야한다.<br> 주주들 돈뜯어서 해야하지 않을까</p><h2 id="소비재" tabindex="-1">소비재 <a class="header-anchor" href="#소비재" aria-label="Permalink to &quot;소비재&quot;">​</a></h2><p>싼거 많다.</p><ol><li><p>필수 소비재<br> 90~95년생 인구수 많다<br> 집을 사겠죠? 인테리어 하겠지</p></li><li><p>삼성 하닉.<br> 부부면 12억이 떨어짐<br> 집사겠지<br> 리모델링. -&gt; 인테리어</p></li><li><p>주식 올라서 쫄림<br> 돈뺴서 집사겠지 -&gt; 인테리어</p></li></ol><p>B2B말고 B2C비중이 높은 회사 찾아봐라</p><p>현대백화점 사지마라 이미 올랐다<br> 명품사는데 차는 안바꿀까?<br> 독3사를 파는 회사. 외제차 회사도 잘 사시고</p><p>인테리어, 외제차를 이미 샀다<br> 싸서.<br> 그리고 싼걸 찾아서 사야지 추세추종하다 큰일 날 수 있다</p><p>만 갈 수 도 있는데 지금 부터 팔아야 안죽는다<br> 안죽으면 20~30퍼 무조건 먹는다</p><p>산다고해도 소비재 같은거 사야지 큰일 난다.<br> 사도 싼거 사라</p><h3 id="외제차-독3사" tabindex="-1">외제차 독3사 <a class="header-anchor" href="#외제차-독3사" aria-label="Permalink to &quot;외제차 독3사&quot;">​</a></h3><p>3개다 신차나온다고 재고 떨이<br> 돈 넣으면 한달안에 나옴<br> 7월에 이전 재고가 없어질 듯<br> 웨이팅이 6개월씩 걸린다.<br> 그럼 중고차가? 뜨지 않을까</p><p>출하기간이 늘면 중고차 밸류가 늘어나겠다</p><h2 id="장이-좋다" tabindex="-1">장이 좋다 <a class="header-anchor" href="#장이-좋다" aria-label="Permalink to &quot;장이 좋다&quot;">​</a></h2><p>차값에 2억씩 태우고 싶지 않다.<br> 풀할부?<br> 렌탈, 장기</p><p>돈많아지면 ? 국내여행<br> 신라호텔 주가가 올랐음</p><p>해외 여행은 지금 유류할증 붙어서?안되니까 국내 여행<br> -&gt; 장기,단기 렌탈.</p><p>소비재로 괜찮을 것 같다</p><p>주식 장 떨어지면 소비장도..</p><p>장이 좋을 떄..</p><p>이번하락이 단기일지..도 잘 판별해서 exit해라<br> 싼거사라<br> 하락장 시작하면 큰일난다.</p>',52)])])}const _=b(a,[["render",i]]);export{c as __pageData,_ as default};
